import asyncio,base64,zlib,types,sys,json,hashlib,os,datetime
from services import source_reachability as installed
candidate=types.ModuleType('overview_candidate_source');sys.modules[candidate.__name__]=candidate
raw=zlib.decompress(base64.b64decode(''))
exec(compile(raw,'<read-only-source-candidate>','exec'),candidate.__dict__)
async def sample(module):
 monitor=module.SourceReachability();monitor.observe();await monitor._task
 sources,running=monitor.observe()
 return {'sources':sources,'running':running,'configured_batch_seconds':module.BATCH_SECONDS,'configured_refresh_seconds':module.REFRESH_SECONDS}
async def main():
 before=await sample(installed);after=await sample(candidate)
 print('SOURCE_COMPARISON '+json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'installed_sha':os.getenv('RENDER_GIT_COMMIT'),'candidate_module_sha256':hashlib.sha256(raw).hexdigest(),'not_installed':True,'database_or_generation_work':False,'before':before,'after':after}),flush=True)
asyncio.run(main())
